    def get_cached_decimals(self, networkCode: str, tokenAddress: str):
        cache = self.safe_dict(self.options, 'decimalsCache', {})
        cacheKey = self.build_decimals_cache_key(networkCode, tokenAddress)
        return self.safe_integer(cache, cacheKey)

    def set_cached_decimals(self, networkCode: str, tokenAddress: str, decimals: int):
        cache = self.safe_dict(self.options, 'decimalsCache', {})
        cacheKey = self.build_decimals_cache_key(networkCode, tokenAddress)
        cache[cacheKey] = decimals
        self.options['decimalsCache'] = cache

    def decode_uint256_hex(self, resultHex: str) -> float:
        normalizedHex = resultHex[2:] if resultHex.startswith('0x') else resultHex
        if len(normalizedHex) < 64:
            raise ExchangeError(self.id + ' RPC result too short to decode uint256: ' + resultHex)
        return int(normalizedHex[0:64], 16)

    def decode_quoter_revert_data(self, revertData: str):
        normalizedHex = revertData[2:] if revertData.startswith('0x') else revertData
        if (len(normalizedHex) >= 8) and (normalizedHex[0:8] == self.get_error_string_selector()):
            return None
        expectedLength = self.get_quoter_output_word_count() * 64
        if len(normalizedHex) == expectedLength:
            return '0x' + normalizedHex
        return None

    def decode_quoter_amount_out(self, resultHex: str) -> float:
        normalizedHex = resultHex[2:] if resultHex.startswith('0x') else resultHex
        if len(normalizedHex) < 64:
            raise ExchangeError(self.id + ' quoter result too short to decode amountOut: ' + resultHex)
        return int(normalizedHex[0:64], 16)

    def eth_call(self, rpcUrl: str, toAddress: str, calldata: str, params={}) -> str:
        requestBody = {
            'jsonrpc': '2.0',
            'id': 1,
            'method': 'eth_call',
            'params': [
                {
                    'to': toAddress,
                    'data': calldata,
                },
                'latest',
            ],
        }
        response = self.fetch2(rpcUrl, 'public', 'POST', params, {
            'Content-Type': 'application/json',
        }, self.json(requestBody))
        result = self.safe_string(response, 'result')
        if result is not None:
            return result
        error = self.safe_dict(response, 'error')
        if error is not None:
            revertData = self.safe_string(error, 'data')
            if revertData is not None:
                decodedResult = self.decode_quoter_revert_data(revertData)
                if decodedResult is not None:
                    return decodedResult
            errorMessage = self.safe_string(error, 'message')
            raise ExchangeError(self.id + ' eth_call failed: ' + errorMessage)
        raise ExchangeError(self.id + ' eth_call returned no result')

    def fetch_token_decimals(self, networkCode: str, tokenAddress: str, params={}) -> int:
        cachedDecimals = self.get_cached_decimals(networkCode, tokenAddress)
        if cachedDecimals is not None:
            return cachedDecimals
        rpcUrl = self.get_rpc_url(networkCode)
        resultHex = self.eth_call(rpcUrl, tokenAddress, self.get_decimals_selector(), params)
        decimals = self.decode_uint256_hex(resultHex)
        self.set_cached_decimals(networkCode, tokenAddress, decimals)
        return decimals

    def build_uniswap_v3_quoter_calldata(self, tokenIn: str, tokenOut: str, amountIn, fee: int) -> str:
        encodedAmountIn = self.coerce_amount_in_for_abi_encode(amountIn)
        encodedParams = self.eth_abi_encode(
            ['address', 'address', 'uint256', 'uint24', 'uint160'],
            [tokenIn, tokenOut, encodedAmountIn, fee, 0]
        )
        return '0x' + self.get_uniswapv3_quote_selector()[2:] + self.binary_to_base16(encodedParams)

    def build_algebra_quoter_calldata(self, tokenIn: str, tokenOut: str, deployer: str, amountIn) -> str:
        encodedAmountIn = self.coerce_amount_in_for_abi_encode(amountIn)
        encodedParams = self.eth_abi_encode(
            ['address', 'address', 'address', 'uint256', 'uint160'],
            [tokenIn, tokenOut, deployer, encodedAmountIn, 0]
        )
        return '0x' + self.get_algebra_quote_selector()[2:] + self.binary_to_base16(encodedParams)

    def get_effective_uniswap_fee(self, route: dict, params={}) -> int:
        paramsFee = self.safe_integer(params, 'fee')
        if paramsFee is not None:
            return paramsFee
        routeFee = self.safe_integer(route, 'fee')
        if routeFee is None:
            raise ExchangeError(self.id + ' missing fee for uniswapv3 route')
        return routeFee

    def build_quoter_calldata_for_market(self, market: Market, params={}) -> dict:
        symbol = self.safe_string(market, 'symbol')
        parsed = self.ob_parse_network_dex_symbol(symbol)
        networkCode = self.safe_string(parsed, 'networkCode')
        dexCode = self.safe_string(parsed, 'dexCode')
        route = self.resolve_quoter_route(networkCode, dexCode)
        engine = self.safe_string(route, 'engine')
        quoter = self.safe_string(route, 'quoter')
        baseId = self.safe_string(market, 'baseId')
        quoteId = self.safe_string(market, 'quoteId')
        baseDecimals = self.fetch_token_decimals(networkCode, baseId, params)
        amountIn = self.build_amount_in_from_decimals(baseDecimals)
        calldata: str
        if engine == 'algebra':
            deployer = self.safe_string(route, 'deployer', self.get_zero_address())
            calldata = self.build_algebra_quoter_calldata(baseId, quoteId, deployer, amountIn)
        elif engine == 'uniswapv3':
            fee = self.get_effective_uniswap_fee(route, params)
            calldata = self.build_uniswap_v3_quoter_calldata(baseId, quoteId, amountIn, fee)
        else:
            raise NotSupported(self.id + ' unsupported quoter engine ' + engine)
        return {
            'networkCode': networkCode,
            'quoter': quoter,
            'calldata': calldata,
            'baseDecimals': baseDecimals,
            'quoteId': quoteId,
        }

    def fetch_quoter_amount_out(self, market: Market, params={}) -> dict:
        quoteRequest = self.build_quoter_calldata_for_market(market, params)
        networkCode = self.safe_string(quoteRequest, 'networkCode')
        quoter = self.safe_string(quoteRequest, 'quoter')
        calldata = self.safe_string(quoteRequest, 'calldata')
        quoteId = self.safe_string(quoteRequest, 'quoteId')
        baseDecimals = self.safe_integer(quoteRequest, 'baseDecimals')
        rpcUrl = self.get_rpc_url(networkCode)
        resultHex = self.eth_call(rpcUrl, quoter, calldata, params)
        amountOut = self.decode_quoter_amount_out(resultHex)
        quoteDecimals = self.fetch_token_decimals(networkCode, quoteId, params)
        last = amountOut / math.pow(10, quoteDecimals)
        return {
            'amountOut': amountOut,
            'last': last,
            'baseDecimals': baseDecimals,
            'quoteDecimals': quoteDecimals,
            'resultHex': resultHex,
        }

    def parse_ticker_from_quote(self, market: Market, quoteInfo: dict) -> Ticker:
        symbol = self.safe_string(market, 'symbol')
        last = self.number_to_string(self.safe_number(quoteInfo, 'last'))
        timestamp = self.seconds()
        return self.safe_ticker({
            'symbol': symbol,
            'timestamp': timestamp,
            'datetime': self.iso8601(timestamp * 1000),
            'high': None,
            'low': None,
            'bid': last,
            'bidVolume': None,
            'ask': last,
            'askVolume': None,
            'vwap': None,
            'open': None,
            'close': last,
            'last': last,
            'previousClose': None,
            'change': None,
            'percentage': None,
            'average': None,
            'baseVolume': None,
            'quoteVolume': None,
            'info': quoteInfo,
        }, market)

    def fetch_markets(self, params={}) -> List[Market]:
        """
        fetches markets; returns empty by default(markets loaded on demand)
        :param dict [params]: extra parameters specific to the exchange API endpoint
        :returns Market[]: an array of market structures
        """
        return []

    def fetch_ticker(self, symbol: str, params={}) -> Ticker:
        """
        fetches a price ticker for a market via on-chain quoter eth_call
        :param str symbol: unified address-pair symbol with @networknot dex suffix
        :param dict [params]: extra parameters specific to the exchange API endpoint
        :param int [params.fee]: optional Uniswap V3 fee tier override
        :returns dict: a `ticker structure <https://docs.ccxt.com/?id=ticker-structure>`
        """
        self.load_markets()
        resolveResult = self.resolve_markets([symbol], params)
        market = resolveResult['marketsBySymbol'][symbol]
        quoteInfo = self.fetch_quoter_amount_out(market, params)
        ticker = self.parse_ticker_from_quote(market, quoteInfo)
        ticker['symbol'] = symbol
        return ticker

    def fetch_tickers(self, symbols: Strings = None, params={}) -> Tickers:
        """
        fetches price tickers for multiple markets; one eth_call per symbol
        :param str[] symbols: list of unified address-pair symbols with @networknot dex suffix
        :param dict [params]: extra parameters specific to the exchange API endpoint
        :returns dict: a dictionary of `ticker structures <https://docs.ccxt.com/?id=ticker-structure>`
        """
        if symbols is None:
            raise ArgumentsRequired(self.id + ' fetchTickers() requires a non-empty symbols argument')
        symbolsLength = len(symbols)
        if symbolsLength == 0:
            raise ArgumentsRequired(self.id + ' fetchTickers() requires a non-empty symbols argument')
        self.load_markets()
        resolveResult = self.resolve_markets(symbols, params)
        marketsBySymbol = resolveResult['marketsBySymbol']
        result = {}
        for symbolIndex in range(0, symbolsLength):
            symbol = symbols[symbolIndex]
            market = self.safe_value(marketsBySymbol, symbol)
            quoteInfo = self.fetch_quoter_amount_out(market, params)
            ticker = self.parse_ticker_from_quote(market, quoteInfo)
            ticker['symbol'] = symbol
            result[symbol] = ticker
        return result

    def ob_load_markets_for_symbols(self, symbols: List[str], reload=False, params={}) -> List[dict]:
        """
        lazily resolves and populates self.markets for the given symbols
        :param str[] symbols: list of address-pair symbols with @networknot dex suffix
        :param boolean reload: when True, re-fetch symbols even if already cached in self.markets
        :param dict params: extra parameters specific to the exchange API endpoint
        :returns dict[]: empty list; ob_alchemy returns fixed market status structures
        """
        if symbols is None:
            raise ArgumentsRequired(self.id + ' obLoadMarketsForSymbols() requires a non-empty symbols argument')
        symbolsLength = len(symbols)
        if symbolsLength == 0:
            raise ArgumentsRequired(self.id + ' obLoadMarketsForSymbols() requires a non-empty symbols argument')
        self.load_markets()
        symbolsToResolve = []
        for symbolIndex in range(0, symbolsLength):
            symbol = symbols[symbolIndex]
            if reload:
                self.remove_cached_market_symbol(symbol)
                symbolsToResolve.append(symbol)
            elif not self.is_market_symbol_cached(symbol):
                symbolsToResolve.append(symbol)
        if len(symbolsToResolve) > 0:
            self.resolve_markets(symbolsToResolve, params)
        return []

    def sign(self, path, api, method, params, headers, body):
        return {'url': path, 'method': method, 'headers': headers, 'body': body}

    def is_transient_alchemy_gateway_http_error(self, httpCode: int, body: str, response) -> bool:
        return httpCode == 403 and (body == '' or body is None) and response is None

    def handle_errors(self, httpCode: int, reason: str, url: str, method: str, headers: dict, body: str, response, requestHeaders, requestBody):
        if self.is_transient_alchemy_gateway_http_error(httpCode, body, response):
            raise OperationFailed(self.id + ' transient gateway 403 on ' + url)
        if response is None:
            return None
        if httpCode == 429:
            raise RateLimitExceeded(self.id + ' ' + body)
        if httpCode == 401 or httpCode == 403:
            raise AuthenticationError(self.id + ' ' + body)
        return None
